20	describe('DefaultCatalogScmEventsService', () => {
21	  it('should publish and subscribe to events', async () => {
22	    const service = new DefaultCatalogScmEventsService();
23	
24	    const subscriber1 = {
25	      onEvents: jest.fn(),
26	    };
27	    const subscriber2 = {
28	      onEvents: jest.fn(),
29	    };
30	
31	    service.subscribe(subscriber1);
32	    service.subscribe(subscriber2);
33	
34	    await service.publish([
35	      {
36	        type: 'location.created',
37	        url: 'https://github.com/backstage/backstage',
38	      },
39	    ]);
40	
41	    expect(subscriber1.onEvents).toHaveBeenCalledWith([
42	      {
43	        type: 'location.created',
44	        url: 'https://github.com/backstage/backstage',
45	      },
46	    ]);
47	    expect(subscriber2.onEvents).toHaveBeenCalledWith([
48	      {
49	        type: 'location.created',
50	        url: 'https://github.com/backstage/backstage',
51	      },
52	    ]);
53	  });
54	
55	  it('waits for all subscribers to acknowledge the events', async () => {
56	    const service = new DefaultCatalogScmEventsService();
57	
58	    const work1 = createDeferred<void>();
59	    const work2 = createDeferred<void>();
60	
61	    const subscriber1 = {
62	      onEvents: jest.fn().mockImplementation(async () => {
63	        await work1;
64	      }),
65	    };
66	    const subscriber2 = {
67	      onEvents: jest.fn().mockImplementation(async () => {
68	        await work2;
69	      }),
70	    };
71	
